/bin/bash -lc "python - <<'PY'
import json
from dataclasses import FrozenInstanceError
from api import run
from core import solve
from model import Result
from render import present
from service import compute

assert compute([{'a': 1}, []]) == Result({'ok': True, 'document': {'a': 1}})
try:
    compute([1, []]).value = 2
    raise AssertionError('Result must be frozen')
except FrozenInstanceError:
    pass
assert present(Result({'x': [1]})) == '{\"x\": [1]}'

source = {'a': [1, 2], 'x/y': {'~': 4}}
ops = [['add', '/a/1', 9], ['replace', '/x~1y/~0', 5], ['test', '/a/1', 9]]
assert solve([source, ops]) == {'ok': True, 'document': {'a': [1, 9, 2], 'x/y': {'~': 5}}}
assert source == {'a': [1, 2], 'x/y': {'~': 4}}
assert solve([{'a': 1}, [['replace', '/a', 2], ['test', '/a', 3]]]) == {'ok': False, 'document': {'a': 1}}
assert solve([1, [['replace', '', 2]]]) == {'ok': True, 'document': 2}
assert solve([1, [['remove', '']]]) == {'ok': True, 'document': None}
for path in ['/a/00', '/a/-', '/a/-1', '/a/2']:
    assert solve([{'a': [1]}, [['remove', path]]])['ok'] is False, path
assert solve([{'a': [1]}, [['add', '/a/-', 2]]]) == {'ok': True, 'document': {'a': [1, 2]}}
assert json.loads(run(json.dumps([[{'n': 1}, []], [{'n': 2}, [['add', '/x', 3]]]]))) == [
    {'ok': True, 'document': {'n': 1}}, {'ok': True, 'document': {'n': 2, 'x': 3}}
]
print('validation passed')
